import {mean,pct,sorted} from './stats.js';
import {compareRecent,compareCategories} from './attendance.js';
import {analyzeRetention} from './retention.js';
export function memberEngagement(rows){
  const ret=analyzeRetention(rows),records=ret.available?ret.perMeeting.map(r=>({...r,new_members:r.newMembers,returning_members:r.returning})):rows.filter(r=>r.returning_members!=null&&r.returning_members<=r.attendance&&(r.new_members==null||r.new_members+r.returning_members===r.attendance));
  const c=compareRecent(rows),recent=records.filter(r=>c.recentIds.includes(r.id)),previous=records.filter(r=>c.previousIds.includes(r.id));
  const share=a=>a.reduce((s,r)=>s+r.returning_members,0)/(a.reduce((s,r)=>s+r.attendance,0)||1);
  return{available:records.length>0,sampleSize:records.length,source:ret.available?'Anonymous member IDs':'Reported member counts',returningShare:records.length?share(records):null,averageNew:mean(records.filter(r=>r.new_members!=null).map(r=>r.new_members)),averageReturning:mean(records.map(r=>r.returning_members)),trend:c.available&&recent.length===3&&previous.length===3?{recent:share(recent),previous:share(previous),percentagePoints:(share(recent)-share(previous))*100,recentCount:mean(recent.map(r=>r.returning_members)),previousCount:mean(previous.map(r=>r.returning_members)),percentChange:pct(mean(recent.map(r=>r.returning_members)),mean(previous.map(r=>r.returning_members)))}:null,warnings:['Returning-attendee share describes turnout, not whether the same newcomers return. Cohort retention needs anonymous IDs.'],excludedRows:rows.filter(r=>!records.some(p=>p.id===r.id)).map(r=>({id:r.id,reason:'Missing or inconsistent member counts.'}))};
}
export function promotionTiming(rows){const valid=rows.filter(r=>r.days_promoted_before!=null),groups=compareCategories(valid.map(r=>({...r,type:r.days_promoted_before>=3?'3+ days ahead':'0–2 days ahead'})),'type'),c=compareRecent(rows),recent=valid.filter(r=>c.recentIds.includes(r.id)),previous=valid.filter(r=>c.previousIds.includes(r.id));return{...groups,field:'days_promoted_before',trend:c.available&&recent.length===3&&previous.length===3?{recent:mean(recent.map(r=>r.days_promoted_before)),previous:mean(previous.map(r=>r.days_promoted_before))}:null,warnings:['Promotion timing is an association. The three-day grouping is descriptive, not an optimal lead-time rule.'],excludedRows:rows.filter(r=>r.days_promoted_before==null).map(r=>({id:r.id,reason:'Promotion lead time missing.'}))}}
export function signupEngagement(rows){const valid=rows.filter(r=>r.signups>0);return{available:valid.length>0,sampleSize:valid.length,averageSignups:mean(rows.filter(r=>r.signups!=null).map(r=>r.signups)),attendancePerSignup:valid.length?valid.reduce((s,r)=>s+r.attendance,0)/valid.reduce((s,r)=>s+r.signups,0):null,warnings:['Attendance divided by pre-meeting signups is an aggregate ratio, not a tracked conversion rate. Walk-ins can make it exceed 100%.']}}
export function analyticsCoverage(rows){const n=k=>rows.filter(r=>r[k]!=null).length,member=memberEngagement(rows);return[{label:'True cohort retention',count:analyzeRetention(rows).rate!=null?rows.length:0,field:'complete anonymous member IDs with follow-up meetings'},{label:'Attendance trends',count:rows.length,field:'date + attendance'},{label:'Meeting formats',count:n('type'),field:'Meeting Type'},{label:'Promotion strategies',count:n('promotion'),field:'Promotion Channels'},{label:'Returning attendees',count:member.sampleSize,field:'New Members + Returning Members (or anonymous IDs)'},{label:'Social reach',count:n('reach'),field:'Instagram Reach Before Meeting'},{label:'Promotion timing',count:n('days_promoted_before'),field:'Promotion Started Days Before'},{label:'Signup ratios',count:rows.filter(r=>r.signups>0).length,field:'Signups Before Meeting (positive values)'}].map(x=>({...x,available:x.count>0,total:rows.length}))}
export function recentFormat(rows){const data=sorted(rows),recent=data.slice(-3),previous=data.slice(0,-3),groups=compareCategories(previous,'type');return{sampleSize:recent.length,counts:[...new Set(recent.map(r=>r.type).filter(Boolean))].map(name=>({name,count:recent.filter(r=>r.type===name).length,historical:groups.groups.find(g=>g.name===name)??null})),historical:groups}}
